  // Calculate mean and standard deviation of each column
  #pragma omp parallel for reduction(+:mean[:], stddev[:])
  for (int j = 0; j < m; j++) {
    float sum = 0.0;
    float count = 0.0;
    for (int i = 0; i < n; i++) {
      sum += data[i][j];
      count++;
    }
    mean[j] = sum / count;
    stddev[j] = sqrt(sum * sum / count - mean[j] * mean[j]);
  }

  // Center and reduce data
  #pragma omp parallel for reduction(+:symmat[:])
  for (int j = 0; j < m; j++) {
    for (int i = 0; i < n; i++) {
      data[i][j] -= mean[j];
      data[i][j] /= sqrt(float_n) * stddev[j];
    }
  }

  // Compute pairwise correlations
  #pragma omp parallel for reduction(+:symmat[:])
  for (int j1 = 0; j1 < m; j1++) {
    for (int j2 = 0; j2 < m; j2++) {
      symmat[j1][j2] = 0.0;
      for (int i = 0; i < n; i++) {
        symmat[j1][j2] += data[i][j1] * data[i][j2];
      }
    }
  }

  // Set diagonal elements to 1.0
  for (int i = 0; i < m; i++) {
    symmat[i][i] = 1.0;
  }
