// Function to compute the Gram-Schmidt process using OpenMP
void kernel_gramschmidt(int ni, int nj, DATA_TYPE* A, DATA_TYPE* R, DATA_TYPE* Q) {
    // Initialize the upper triangular matrix R
    for (int k = 0; k < nj; ++k) {
        R[k][k] = 0; // Set the diagonal element to zero
    }

    // Perform Gram-Schmidt process using OpenMP
#pragma omp parallel for
    for (int k = 0; k < nj; ++k) {
        // Compute the norm of the current vector
        double nrm = 0;
        for (int i = 0; i < ni; ++i) {
            nrm += A[i][k] * A[i][k];
        }
        nrm = sqrt(nrm);

        // Normalize the vector
        for (int i = 0; i < ni; ++i) {
            Q[i][k] = A[i][k] / nrm;
        }

        // Orthogonalize against subsequent vectors
        for (int j = k + 1; j < nj; ++j) {
            R[k][j] = 0; // Initialize the off-diagonal element to zero

            // Compute the dot product
            double dot_product = 0;
            for (int i = 0; i < ni; ++i) {
                dot_product += Q[i][k] * A[i][j];
            }

            // Update the vector after orthogonalization
            for (int i = 0; i < ni; ++i) {
                A[i][j] -= dot_product * Q[i][k];
            }
        }
    }
}

