void kernel_durbin(int n, DATA_TYPE POLYBENCH_2D(y, N, N, n, n),
                   DATA_TYPE POLYBENCH_2D(sum, N, N, n, n),
                   DATA_TYPE POLYBENCH_1D(alpha, N, n),
                   DATA_TYPE POLYBENCH_1D(beta, N, n),
                   DATA_TYPE POLYBENCH_1D(r, N, n),
                   DATA_TYPE POLYBENCH_1D(out, N, n))
{
    // Initialize y with the first element of r
    y[0][0] = r[0];

    // Initialize beta and alpha
    beta[0] = 0;
    alpha[0] = r[0];

    // Main loop for parallel computation
#pragma omp parallel for private(k, i, j) reduction(+:sum[i][j])
    for (k = 1; k < n; ++k) {
        // Update beta
        beta[k] = beta[k-1] + alpha[k-1] * beta[k-1];

        // Populate sum array
        for (i = 0; i <= k; ++i) {
            sum[i][k] = 0;
            for (j = 0; j < i; ++j) {
                sum[i][k] += r[j] * beta[j];
            }
            sum[i][k] *= alpha[k];
        }

        // Calculate alpha
        alpha[k] = sum[k][k];

        // Update y
        for (i = 0; i <= k; ++i) {
            y[k][i] = y[k-1][i] + sum[i][k];
        }
    }

    // Final output accumulation
#pragma omp parallel for private(i)
    for (i = 0; i < n; ++i) {
        out[i] = y[n-1][i];
    }
}

