void kernel_ludcmp(int n, double A[N+1][N+1], double b[N+1], double x[N+1], double y[N+1]) {
    // Initialize b to 1.0
    b[0] = 1.0;

    // Parallelize the outer loop over rows
#pragma omp parallel for
    for (int i = 0; i < n; i++) {
        double w;
        double sum = 0.0;

        // Calculate elements below the diagonal
        for (int j = 0; j <= i; j++) {
            w = A[j][i];
            for (int k = 0; k < j; k++) {
                w -= A[k][i] * A[j][k];
            }
            A[j][i] = w;
        }

        // Synchronize threads
#pragma omp critical
        {
            // Update the first half of the matrix
            for (int j = i + 1; j < N; j++) {
                sum = 0.0;
                for (int k = 0; k < i; k++) {
                    sum += A[k][i] * A[j][k];
                }
                A[j][i] = A[j][i] - sum;
            }
        }

        // Solve for intermediate vector y
        y[i] = b[i];

        // Parallelize the inner loop over rows
#pragma omp parallel for
        for (int j = i + 1; j < N; j++) {
            double sum = 0.0;
            for (int k = 0; k < i; k++) {
                sum += A[k][i] * y[j];
            }
            y[j] = y[j] - sum;
        }

        // Back substitution
        x[n - 1] = y[n - 1] / A[n - 1][n - 1];
        for (int i = n - 2; i >= 0; i--) {
            double sum = 0.0;
            for (int j = i + 1; j < N; j++) {
                sum += A[j][i] * x[j];
            }
            x[i] = (y[i] - sum) / A[i][i];
        }
    }
}

